    case 1u: { return cmap_color(src); }
    case 2u: { return unpack_rgba(src); }
    case 3u: { return vec4<f32>(1.0); }
    case 4u: { return class_color(src); }
    default: { return unpack_rgba(p.flat_rgba); }
